module spaceship_destroyer (\n    input clk, rst_n, start,\n    input signed [7:0] group1_0, group1_1,\n    input signed [7:0] group2_0, group2_1,\n    input [1:0] n, m,\n    output reg [7:0] result,\n    output reg done\n);\n    // State declarations\n    localparam [1:0] IDLE          = 2'd0;\n    localparam [1:0] PREPARE_SUMS  = 2'd1;\n    localparam [1:0] ITERATE       = 2'd2;\n    localparam [1:0] DONE_STATE    = 2'd3;\n    \n    // Data registers\n    reg signed [7:0] g1 [0:1];\n    reg signed [7:0] g2 [0:1];\n    reg signed [7:0] sums [0:3];\n    \n    // Control registers\n    reg [1:0] state, next_state;\n    reg [1:0] i, j;\n    reg [7:0] best;\n    reg [7:0] current_total;\n    reg bit0_group1, bit1_group1, bit0_group2, bit1_group2;\n    \n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            // Reset all registers\n            state <= IDLE;\n            done <= 1'b0;\n            result <= 8'd0;\n            g1[0] <= 8'd0;\n            g1[1] <= 8'd0;\n            g2[0] <= 8'd0;\n            g2[1] <= 8'd0;\n            for (int k=0; k<4; k=k+1) sums[k] <= 8'd0;\n            i <= 2'd0;\n            j <= 2'd0;\n            best <= 8'd0;\n            current_total <= 8'd0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    best <= 8'd0;\n                    if (start) begin\n                        g1[0] <= group1_0;\n                        g1[1] <= group1_1;\n                        g2[0] <= group2_0;\n                        g2[1] <= group2_1;\n                        state <= PREPARE_SUMS;\n                    end\n                end\n                \n                PREPARE_SUMS: begin\n                    if (n >= 2'd1 && m >= 2'd1) sums[0] <= g1[0] + g2[0];\n                    else sums[0] <= 8'd0;\n                    \n                    if (n >= 2'd1 && m >= 2'd2) sums[1] <= g1[0] + g2[1];\n                    else sums[1] <= 8'd0;\n                    \n                    if (n >= 2'd2 && m >= 2'd1) sums[2] <= g1[1] + g2[0];\n                    else sums[2] <= 8'd0;\n                    \n                    if (n >= 2'd2 && m >= 2'd2) sums[3] <= g1[1] + g2[1];\n                    else sums[3] <= 8'd0;\n                    \n                    i <= 2'd0;\n                    j <= 2'd0;\n                    state <= ITERATE;\n                end\n                \n                ITERATE: begin\n                    bit0_group1 = (n >= 2'd1) && (\n                        (sums[i] - g1[0] == g2[0]) || (sums[i] - g1[0] == g2[1]) || \n                        (sums[j] - g1[0] == g2[0]) || (sums[j] - g1[0] == g2[1])\n                    );\n                    \n                    bit1_group1 = (n >= 2'd2) && (\n                        (sums[i] - g1[1] == g2[0]) || (sums[i] - g1[1] == g2[1]) || \n                        (sums[j] - g1[1] == g2[0]) || (sums[j] - g1[1] == g2[1])\n                    );\n                    \n                    bit0_group2 = (m >= 2'd1) && (\n                        (sums[i] - g2[0] == g1[0]) || (sums[i] - g2[0] == g1[1]) || \n                        (sums[j] - g2[0] == g1[0]) || (sums[j] - g2[0] == g1[1])\n                    );\n                    \n                    bit1_group2 = (m >= 2'd2) && (\n                        (sums[i] - g2[1] == g1[0]) || (sums[i] - g2[1] == g1[1]) || \n                        (sums[j] - g2[1] == g1[0]) || (sums[j] - g2[1] == g1[1])\n                    );\n                    \n                    current_total = bit0_group1 + bit1_group1 + bit0_group2 + bit1_group2;\n                    \n                    if (current_total > best) best <= current_total;\n                    \n                    if (j == 2'd3) begin\n                        j <= 2'd0;\n                        if (i == 2'd3) begin\n                            state <= DONE_STATE;\n                        end else begin\n                            i <= i + 2'd1;\n                        end\n                    end else begin\n                        j <= j + 2'd1;\n                    end\n                end\n                \n                DONE_STATE: begin\n                    result <= best;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule